using Catalog.Domain.Products;
using ProductEntity = Catalog.Domain.Products.Product;
using Catalog.Domain.Products.ValueObjects;

namespace Catalog.Application.Features.Product.Commands.CreateCatalogProduct;

/// <summary>The largest product ID; product IDs are not generated by the database.</summary>
public sealed class LastProductIdSpec : Specification<ProductEntity, ProductId>
{
    public LastProductIdSpec()
    {
        Query.OrderByDescending(x => x.Id).Take(1).AsNoTracking();
        Query.Select(x => x.Id);
    }
}
